function words(text){ if(!text) return 0; return (String(text).match(/\S+/g)||[]).length; }
function readTime(wordCount, wpm){ wpm=+wpm; wordCount=+wordCount; if(!(wpm>0)) return {error:'语速须为正'}; return wordCount/wpm*60; }
function format(sec){ sec=Math.max(0,Math.round(+sec||0)); var m=Math.floor(sec/60), s=sec%60; return m+':'+(s<10?'0':'')+s; }
var EXPORTS={words:words, readTime:readTime, format:format};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ScriptTimerForgePure = EXPORTS; }
